"""Original critical-care organ support: renal and neurological emergencies."""
from qbank_authoring import question,ref
rows=[]
AK=ref('KDIGO published AKI guideline: renal replacement support','https://kdigo.org/wp-content/uploads/2019/01/KDIGO-2012-AKI-Guideline-English.pdf')
ST=ref('STARRT-AKI randomized trial','https://www.nejm.org/doi/full/10.1056/NEJMoa2000741')
CE=ref('Neurocritical Care Society cerebral edema guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC7272487/')
SE=ref('Adult status epilepticus acute management guidance: 2025','https://pmc.ncbi.nlm.nih.gov/articles/PMC12062632/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A patient with AKI has refractory hyperkalemia with ECG changes and pulmonary edema despite appropriate medical treatment. Which renal-support principle is correct?', 'Urgent renal replacement therapy is indicated by life-threatening complications',[
 ('Wait until creatinine reaches an arbitrary fixed threshold','Complications can mandate treatment before any particular creatinine value.'),('Use urine output alone to overrule the immediate complications','The total clinical context determines urgency.'),('Delay until a full etiological biopsy is available','Life-threatening electrolyte or fluid problems need immediate management.')],
 'Treat the urgent physiological failure','**Refractory dangerous potassium, acid-base or fluid complications can require immediate RRT.**',['Continue temporizing treatment while arranging definitive support.','Creatinine is a marker of kidney dysfunction, not the sole start criterion.'], '**Choose the modality according to stability and the required correction.**',['Treat the precipitating cause and medication contributors.','Monitor for rebound and ongoing electrolyte shifts.'],[['Trigger','Life-threatening complication'],['Creatinine','Not an isolated treatment gate'],['Modality','Clinical stability and correction needs']],[AK],style='clinical_scenario')

q('A critically ill patient has severe AKI but no urgent dialysis complication and can be closely monitored. What did STARRT-AKI support?', 'Routine accelerated RRT initiation did not improve survival compared with a standard strategy in the studied population',[
 ('Every AKI patient should receive dialysis immediately on diagnosis','The trial does not support that universal strategy.'),('Dialysis should be withheld even when refractory hyperkalemia develops','Urgent indications require treatment.'),('The trial proved one creatinine threshold is sufficient for all patients','Clinical assessment remains necessary.')],
 'Do not equate severe AKI with an automatic immediate circuit','**An accelerated strategy did not provide the expected survival advantage in eligible patients without mandatory urgent indications.**',['Some patients in a standard strategy recover without RRT.','This finding does not apply to withholding treatment for immediate physiological danger.'], '**Use close monitoring and explicit escalation criteria.**',['Assess fluid balance, potassium, acidosis and uremic complications.','Discuss trajectory and overall prognosis rather than a number alone.'],[['No urgent indication','Standard monitored strategy can be appropriate'],['Urgent complication','Treat promptly'],['Outcome','No universal accelerated-start survival benefit']],[ST],style='clinical_scenario')

q('Why is CRRT often chosen over conventional intermittent hemodialysis in a markedly hemodynamically unstable patient?', 'It permits slower continuous fluid and solute management with potential tolerability advantages',[
 ('It has proven universal survival superiority for every AKI patient','No such universal outcome advantage is established.'),('It never changes electrolytes or temperature','CRRT can cause important electrolyte and thermal changes.'),('It eliminates the need to prescribe net fluid removal','Removal still requires careful individualized prescription.')],
 'Match the modality to physiology and care requirements','**Continuous therapy can make gradual correction easier in unstable patients.**',['Intermittent or prolonged intermittent modalities may still be suitable in selected circumstances.','The choice depends on urgency, resources, neurological risk and hemodynamic tolerance.'], '**Distinguish clearance dose from net fluid removal.**',['Monitor perfusion and electrolytes as removal proceeds.','CRRT is support while the cause is treated, not a cure for every AKI mechanism.'],[['CRRT','Gradual continuous support'],['IHD','Faster intermittent correction'],['Selection','Clinical context rather than universal superiority']],[AK])

q('What is the usual evidence-based delivered CRRT effluent dose range for most critically ill adults with AKI, excluding special clearance requirements?', '20–25 mL/kg/hour',[
 ('5–10 mL/kg/hour','This is below the usual delivered-dose range for standard AKI support.'),('40–50 mL/kg/hour for every patient','Higher routine intensity has not shown universal outcome benefit and adds losses.'),('80–100 mL/kg/hour for every patient','This is not a standard universal AKI dose.')],
 'Prescribed and delivered dose are not identical','**The conventional delivered effluent target is twenty to twenty-five mL/kg/hour.**',['Downtime and interruptions can reduce actual delivery.','Special metabolic or toxicological indications may require a different prescription.'], '**Audit delivered treatment rather than only the order.**',['Replace lost phosphate and other electrolytes as indicated.','Do not confuse effluent clearance with net fluid removal from the patient.'],[['Delivered dose','20–25 mL/kg/h'],['Prescription','May need allowance for downtime'],['Net ultrafiltration','Separate clinical target']],[AK])

q('During regional citrate anticoagulation, ionized calcium falls, calcium replacement needs rise and the total-to-ionized calcium ratio exceeds 2.5 with metabolic deterioration. What should be considered?', 'Citrate accumulation',[
 ('A guaranteed harmless laboratory artifact','The combined biochemical and clinical trend needs evaluation.'),('Pure respiratory alkalosis as the complete explanation','This does not adequately explain the rising calcium gap and replacement requirement.'),('Normal expected progress requiring no protocol review','Accumulation can become dangerous and requires prompt reassessment.')],
 'Use the calcium gap as part of a syndrome','**Impaired citrate handling can retain citrate-calcium complexes.**',['The total/ionized ratio and increasing calcium needs are useful clues, not an infallible isolated test.','Shock and impaired metabolism can increase risk.'], '**Review the citrate protocol and systemic state promptly.**',['Adjust or stop citrate and use alternative anticoagulation when indicated.','Monitor acid-base balance, ionized calcium and circuit function closely.'],[['Ionized calcium','May fall'],['Total/ionized ratio','Can rise'],['Action','Protocol and perfusion/metabolism review']],[ref('Regional citrate anticoagulation consensus: 2023','https://pmc.ncbi.nlm.nih.gov/articles/PMC10226261/')],style='clinical_scenario')

q('What is the principal anticoagulant mechanism of regional citrate in a CRRT circuit?', 'Chelation of ionized calcium within the extracorporeal circuit',[
 ('Potentiation of antithrombin','This describes the major heparin mechanism.'),('Direct thrombin inhibition','This describes agents such as argatroban or bivalirudin.'),('Irreversible inhibition of platelet cyclooxygenase','This describes aspirin.')],
 'Keep regional anticoagulation and systemic calcium management linked','**Citrate lowers available calcium needed for coagulation in the circuit.**',['Calcium replacement and monitoring are part of the protocol.','Systemic citrate metabolism and calcium balance determine safety.'], '**Monitor both circuit efficacy and patient physiology.**',['A well-anticoagulated filter does not guarantee normal systemic ionized calcium.','Use an experienced protocol with adjustment for metabolic problems.'],[['Circuit calcium','Reduced for anticoagulation'],['Systemic calcium','Monitored/replaced'],['Heparin','Different antithrombin mechanism']],[AK,ref('Citrate anticoagulation consensus','https://pmc.ncbi.nlm.nih.gov/articles/PMC10226261/')])

q('MAP is 85 mmHg and ICP is 25 mmHg. What is the usual simplified cerebral perfusion pressure calculation?', '60 mmHg',[
 ('25 mmHg','This is ICP, not the perfusion gradient.'),('85 mmHg','This ignores intracranial pressure.'),('110 mmHg','CPP is not the sum.')],
 'Cerebral perfusion depends on the pressure gradient','**CPP is approximately MAP minus ICP in the usual simplified model.**',['Here eighty-five minus twenty-five equals sixty.','Venous pressure, reference level and autoregulation can complicate the real physiology.'], '**Address both systemic pressure and intracranial pathology.**',['Avoid hypoxemia and hypotension.','The appropriate target depends on the disease and guideline, not the calculation alone.'],[['MAP','85'],['ICP','25'],['CPP','60']],[CE],style='clinical_scenario')

q('What is the appropriate general role of marked hyperventilation in acute intracranial hypertension?', 'A temporary rescue maneuver in selected impending-herniation situations, not routine prolonged prophylaxis',[
 ('Universal long-term prophylaxis for every brain-injured patient','Sustained hypocapnia can impair cerebral blood flow.'),('A way to lower ICP without any perfusion trade-off','Cerebral vasoconstriction can compromise ischemic tissue.'),('A substitute for definitive neurosurgical evaluation','It does not remove a hematoma or correct the underlying lesion.')],
 'Lowering ICP can come at the cost of blood flow','**Hypocapnia constricts cerebral vessels.**',['This can temporarily reduce intracranial blood volume.','The same effect can worsen cerebral ischemia.'], '**Use short rescue treatment only with a cause-directed plan.**',['Arrange urgent imaging/neurosurgical care and other ICP measures.','Monitor gas exchange and the clinical trajectory.'],[['Effect','Cerebral vasoconstriction'],['Potential benefit','Temporary ICP reduction'],['Risk','Reduced cerebral perfusion']],[CE])

q('A patient is receiving hypertonic saline for intracranial hypertension. Which monitoring is especially relevant?', 'Serum sodium, chloride, acid-base status, renal function and volume/hemodynamic response',[
 ('Only the serum glucose','This does not assess the main osmotic and electrolyte safety issues.'),('Only a daily ANA','This has no role in acute osmotherapy monitoring.'),('Only pulse oximetry without laboratory assessment','Oxygenation does not detect sodium/chloride and renal complications.')],
 'Osmotherapy needs a measurable target and safety limits','**Hypertonic therapy can reduce cerebral edema but can cause systemic electrolyte and renal complications.**',['Choice versus mannitol depends on the neurological syndrome and physiology.','A fixed high sodium target is not a universal substitute for assessing response.'], '**Monitor neurological and systemic effects together.**',['Review cumulative sodium/chloride exposure.','Do not delay definitive cause treatment because ICP temporarily improves.'],[['Desired effect','ICP/edema control'],['Safety','Sodium, chloride and renal monitoring'],['Definitive care','Treat the cause']],[CE])

q('A generalized convulsive seizure has continued beyond 5 minutes. Which medication class is first-line emergency treatment while airway and metabolic assessment proceed?', 'A benzodiazepine by an appropriate rapidly available route',[
 ('A maintenance oral antiseizure tablet as the sole immediate therapy','Absorption and onset are unsuitable for the active emergency.'),('An antipsychotic as the initial antiseizure drug','This does not provide the recommended seizure-termination treatment.'),('A neuromuscular blocker without antiseizure therapy','Paralysis can hide convulsions without stopping cerebral seizures.')],
 'Treat prolonged convulsions before systemic injury accumulates','**Benzodiazepines are first-line for convulsive status epilepticus.**',['Use a route appropriate to access without unnecessary delay.','Check glucose and reversible metabolic causes concurrently.'], '**Proceed promptly to a suitable longer-acting antiseizure agent when needed.**',['Prepare airway/ventilatory support.','Persistent seizures require escalation, not repeated delays between stages.'],[['First stage','Rapid benzodiazepine'],['Next stage','Appropriate second-line loading'],['Persistent activity','Refractory-status pathway']],[SE],style='clinical_scenario')

q('Convulsive status continues despite an adequate benzodiazepine and a suitable second-line antiseizure load. Which next principle is appropriate?', 'Treat refractory status in an ICU-capable setting with continuous EEG and appropriately selected anesthetic/antiseizure therapy',[
 ('Observe indefinitely because two drugs have already been tried','Persistent seizure activity can cause major injury.'),('Use paralysis alone and declare seizure termination when movements stop','Electrical seizures can continue without motor activity.'),('Wait for a routine EEG several days later before escalation','Timely EEG-guided treatment is important.')],
 'Motor silence does not certify cerebral seizure control','**Refractory status requires urgent escalation and physiological support.**',['Continuous EEG guides therapy and detects recurrence.','Choice of anesthetic and targets is individualized to clinical circumstances and expertise.'], '**Continue cause investigation during treatment.**',['Consider infection, metabolic disease, toxins and autoimmune encephalitis when indicated.','Monitor hypotension and complications of prolonged sedation.'],[['Definition','Failure of adequate first/second-line treatment'],['EEG','Confirms electrical response'],['ICU support','Airway, circulation and ongoing therapy']],[SE],style='clinical_scenario')

q('After visible convulsions stop, a patient remains unexpectedly unresponsive without an adequate explanation. Which investigation is particularly important?', 'EEG to assess persistent nonconvulsive seizure activity',[
 ('Serum prolactin alone as a definitive continuous-seizure test','It cannot reliably establish ongoing electrical seizures.'),('A normal pulse oximeter as proof of neurological recovery','Oxygen saturation does not assess seizure activity.'),('Assuming prolonged sedation without reviewing dose or other causes','Medication effects are a differential, but should not exclude NCSE without assessment.')],
 'Persistent altered consciousness needs a structured differential','**Nonconvulsive status can continue after motor activity ceases.**',['Sedation, metabolic disturbance, structural disease and postictal states are alternatives.','EEG provides the relevant electrical information.'], '**Use timely monitoring in a high-risk patient.**',['Review medications and organ function in parallel.','Do not rely on the absence of jerking as the only evidence of seizure control.'],[['No motor activity','Does not exclude seizures'],['EEG','Defines electrical activity'],['Differential','Drugs, metabolic and structural causes']],[SE],style='clinical_scenario')

q('After prolonged sepsis, a patient has diffuse weakness and electrophysiology shows low motor and sensory response amplitudes with relatively preserved conduction velocity. Which mechanism is most likely?', 'Critical illness polyneuropathy',[
 ('Pure critical illness myopathy','Sensory responses are typically preserved in a pure muscle process.'),('Myasthenia gravis','A junctional disorder does not produce the same sensory axonal pattern.'),('An isolated upper motor neuron lesion','This does not explain the diffuse peripheral motor/sensory amplitude changes.')],
 'Use sensory responses to identify an axonal nerve component','**CIP is a sensorimotor axonal polyneuropathy.**',['Motor and sensory amplitudes can both fall.','Myopathy and neuropathy often coexist in critical illness.'], '**Assess reversible contributors and rehabilitation needs.**',['Exclude electrolyte, medication and other neurological causes.','Respiratory weakness can delay liberation from ventilation.'],[['CIP','Motor plus sensory axonal loss'],['Pure CIM','Sensory responses relatively preserved'],['Overlap','Common in ICU weakness']],[ref('Critical-illness neuromuscular electrophysiology: 2026','https://pubmed.ncbi.nlm.nih.gov/42087675/')],style='clinical_scenario')

q('Which finding favors a pure critical illness myopathy over critical illness polyneuropathy?', 'Preserved sensory nerve responses with a compatible myopathic motor-unit pattern',[
 ('Marked sensory axonal amplitude loss','This supports a neuropathic component.'),('A new focal cortical deficit','This suggests a central lesion rather than either diffuse ICU-acquired process.'),('A decremental junctional pattern as the defining finding','This suggests a neuromuscular-junction disorder.')],
 'ICU-acquired weakness is a syndrome with several mechanisms','**Myopathy primarily affects muscle rather than sensory axons.**',['CK can be normal or elevated and is not a definitive separator alone.','Electrophysiology, examination and selected other tests clarify the pattern.'], '**Treat contributors and prevent secondary disability.**',['Optimize nutrition, mobilization when safe and medication exposure.','Do not assume every difficult wean is caused by persistent lung disease.'],[['CIM','Muscle pattern'],['CIP','Sensory and motor nerve injury'],['Function','Requires rehabilitation and follow-up']],[ref('Critical illness neuropathy/myopathy electrophysiology','https://pubmed.ncbi.nlm.nih.gov/42087675/')])

if __name__=='__main__':print(f'Critical organ support draft: {len(rows)} questions')
